import sqlite3Pkg from "sqlite3";

const sqlite3 = (sqlite3Pkg as any).default || sqlite3Pkg;
const DB_PATH = "/home/user/qwik-app/activity.db";

let dbInstance: any = null;

export function getDb(): any {
  if (!dbInstance) {
    dbInstance = new sqlite3.Database(DB_PATH);
    // Configure SQLite for high concurrency and robustness
    dbInstance.serialize(() => {
      dbInstance.run("PRAGMA journal_mode = WAL;");
      dbInstance.run("PRAGMA busy_timeout = 5000;");
      dbInstance.run(`
        CREATE TABLE IF NOT EXISTS ActivityLog (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          path TEXT NOT NULL,
          method TEXT NOT NULL,
          ip TEXT NOT NULL,
          timestamp TEXT NOT NULL,
          duration_ms INTEGER NOT NULL
        )
      `);
    });
  }
  return dbInstance;
}

export function runQuery(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    const db = getDb();
    db.run(sql, params, function (this: any, err: Error | null) {
      if (err) {
        reject(err);
      } else {
        resolve();
      }
    });
  });
}

export function getQuery<T>(sql: string, params: any[] = []): Promise<T | undefined> {
  return new Promise((resolve, reject) => {
    const db = getDb();
    db.get(sql, params, (err: Error | null, row: any) => {
      if (err) {
        reject(err);
      } else {
        resolve(row as T);
      }
    });
  });
}

export function allQuery<T>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    const db = getDb();
    db.all(sql, params, (err: Error | null, rows: any[]) => {
      if (err) {
        reject(err);
      } else {
        resolve(rows as T[]);
      }
    });
  });
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { runQuery } from "../db";

export const onRequest: RequestHandler = async (event) => {
  const url = new URL(event.request.url);
  const path = url.pathname;

  const isLoggedPath = path.startsWith("/api/") || path.startsWith("/admin/");

  if (!isLoggedPath) {
    await event.next();
    return;
  }

  const start = Date.now();
  const timestamp = new Date().toISOString();
  const method = event.request.method;
  const ip = event.clientConn.ip || event.request.headers.get("x-forwarded-for") || "127.0.0.1";

  try {
    await event.next();
  } finally {
    const duration_ms = Date.now() - start;
    try {
      await runQuery(
        "INSERT INTO ActivityLog (path, method, ip, timestamp, duration_ms) VALUES (?, ?, ?, ?, ?)",
        [path, method, ip, timestamp, duration_ms]
      );
    } catch (err) {
      console.error("Database logging error:", err);
    }
  }
};

